        case FONTSHAPER_LINE_BREAK_CLASS_SOT:
        case FONTSHAPER_LINE_BREAK_CLASS_BK:
        case FONTSHAPER_LINE_BREAK_CLASS_CR:
        case FONTSHAPER_LINE_BREAK_CLASS_LF:
        case FONTSHAPER_LINE_BREAK_CLASS_NL:
        case FONTSHAPER_LINE_BREAK_CLASS_SP:
